<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class SuggestionController extends Controller{public function store(Request $r):JsonResponse{$d=$r->validate(['name'=>['nullable','string','max:120'],'email'=>['required','email','max:190'],'category'=>['required',Rule::in(['suggestion','problem','compliment','other'])],'message'=>['required','string','min:10','max:4000'],'page_url'=>['nullable','url','max:1000']]);DB::table('suggestions')->insert([...$d,'user_id'=>$r->user()?->id,'status'=>'new','created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Gracias. Recibimos tu comentario.'],201);}public function index(Request $r):JsonResponse{abort_unless($r->user()->is_admin,403);return response()->json(['data'=>DB::table('suggestions')->latest()->paginate(50)]);}public function update(Request $r,int $suggestion):JsonResponse{abort_unless($r->user()->is_admin,403);$d=$r->validate(['status'=>['required',Rule::in(['new','reviewing','resolved','dismissed'])]]);abort_unless(DB::table('suggestions')->where('id',$suggestion)->update([...$d,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'updated_at'=>now()]),404);return response()->json(['message'=>'Sugerencia actualizada.']);}}
